ambiguous:
A :: struct { value: s32; }
B :: struct { value: s32; }
Answer :: () { result := ifx true then .{value=1} else .{value=2}; }

distinct:
A :: struct { value: s32; }
B :: struct { value: s32; }
Answer :: () { result := ifx true then A.{value=1} else B.{value=2}; }

owned:
#import "std/vec"
A :: struct { values: Vec(u8); }
Answer :: () { result := ifx true then A.{} else .{}; }

foreign:
c :: #system_library "libc";
A :: #type #foreign c;
Answer :: () { result := ifx true then A.{} else .{}; }
